import{_ as e,c as a,o as d,a2 as t}from"./chunks/framework.DdOM6S6U.js";const m=JSON.parse('{"title":"Layout builders","description":"","frontmatter":{"sidebarPos":5,"sidebarTitle":"Layout builders","sidebarGroupTitle":"Cms","outline":"deep"},"headers":[],"relativePath":"guide/cms/layout-builders.md","filePath":"guide/cms/layout-builders.md","lastUpdated":1784841066000}'),s={name:"guide/cms/layout-builders.md"},o=t(`<h1 id="layout-builders" tabindex="-1">Layout builders <a class="header-anchor" href="#layout-builders" aria-label="Permalink to &quot;Layout builders&quot;">​</a></h1><p>A <strong>LayoutBuilder</strong> is a reusable HTML document shell (head / body / footer) — the selected “theme”. <a href="./page-layouts">Page layouts</a> point at a builder; <a href="./stylesheets">stylesheets</a> hang off the builder.</p><p>Rendered by <code>LayoutBladeResolver</code>.</p><h2 id="blade-source-exclusive" tabindex="-1">Blade source (exclusive) <a class="header-anchor" href="#blade-source-exclusive" aria-label="Permalink to &quot;Blade source (exclusive)&quot;">​</a></h2><table><thead><tr><th>Mode</th><th>What is authoritative</th></tr></thead><tbody><tr><td><strong><code>db</code></strong> (default)</td><td><code>blade_segments</code> (<code>head</code>, <code>body</code>, <code>footer</code>) — <code>Blade::render()</code>, wrapped in <code>cms::layout_builder.shell</code></td></tr><tr><td><strong><code>filesystem</code></strong></td><td>Theme blades on disk keyed by <strong><code>slug</code></strong> (and optional <code>blade_view_name</code>)</td></tr></tbody></table><p>Do <strong>not</strong> keep markup in both places. Saving clears the inactive side.</p><p><strong>Default when a row omits <code>blade_source</code>:</strong> <code>cms_layout_builder.default_blade_source</code> = <strong><code>db</code></strong> (<code>MODULAROUS_CMS_LAYOUT_BLADE_SOURCE</code>).</p><h2 id="filesystem-mode-—-resolution-order" tabindex="-1">Filesystem mode — resolution order <a class="header-anchor" href="#filesystem-mode-—-resolution-order" aria-label="Permalink to &quot;Filesystem mode — resolution order&quot;">​</a></h2><p>When <code>blade_source=filesystem</code>:</p><ol><li><strong>Slug theme pack</strong> — if <code>slug</code> is set and any slug segment view exists (usual case; <code>blade_view_name</code> may be <strong><code>NULL</code></strong>)</li><li>Else explicit <strong><code>blade_view_name</code></strong> if that view exists</li><li>Else PageLayout/module <code>page_layout</code> segments inside the package shell</li></ol><h3 id="null-blade-view-name-→-slug-theme-fallback-recommended" tabindex="-1">NULL <code>blade_view_name</code> → slug theme fallback (recommended) <a class="header-anchor" href="#null-blade-view-name-→-slug-theme-fallback-recommended" aria-label="Permalink to &quot;NULL \`blade_view_name\` → slug theme fallback (recommended)&quot;">​</a></h3><p>Production themes often look like this in <code>layout_builders</code>:</p><table><thead><tr><th>name</th><th>slug</th><th>blade_source</th><th>blade_view_name</th></tr></thead><tbody><tr><td>b2press</td><td><code>b2press</code></td><td><code>filesystem</code></td><td><strong><code>NULL</code></strong></td></tr><tr><td>Bootstrap</td><td><code>bootstrap-5-3-8</code></td><td><code>db</code></td><td><code>NULL</code> (uses <code>blade_segments</code>)</td></tr></tbody></table><p>For filesystem + slug, <code>LayoutBladeResolver</code> loads:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cms.layout_builder.{slug}.{segment}</span></span>
<span class="line"><span>cms::layout_builder.{slug}.{segment}</span></span>
<span class="line"><span>vendor.modularous.layout_builder.{slug}.{segment}</span></span></code></pre></div><p>First existing view wins. Host apps typically use the <strong><code>cms.layout_builder.*</code></strong> namespace (no <code>::</code>):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>resources/views/cms/layout_builder/{slug}/head.blade.php</span></span>
<span class="line"><span>resources/views/cms/layout_builder/{slug}/body.blade.php</span></span>
<span class="line"><span>resources/views/cms/layout_builder/{slug}/footer.blade.php</span></span>
<span class="line"><span>resources/views/cms/layout_builder/{slug}/shell.blade.php   # optional</span></span></code></pre></div><p><strong>Example — theme <code>b2press</code>:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>resources/views/cms/layout_builder/b2press/head.blade.php</span></span>
<span class="line"><span>resources/views/cms/layout_builder/b2press/body.blade.php</span></span>
<span class="line"><span>resources/views/cms/layout_builder/b2press/footer.blade.php</span></span></code></pre></div><p>↔ views <code>cms.layout_builder.b2press.head</code> / <code>.body</code> / <code>.footer</code>.</p><p>Same pattern with the Cms module namespace: <code>cms::layout_builder.b2press.head</code> → <code>modules/Cms/Resources/views/layout_builder/b2press/head.blade.php</code> (if present).</p><p>Vendor publish path alternative:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>resources/views/vendor/modularous/layout_builder/{slug}/{segment}.blade.php</span></span></code></pre></div><p>If no slug <code>shell</code> exists, segments are composed with package <code>cms::layout_builder.shell</code>.</p><p>After edits: <code>php artisan view:clear</code>.</p><h3 id="optional-single-master-via-blade-view-name" tabindex="-1">Optional: single master via <code>blade_view_name</code> <a class="header-anchor" href="#optional-single-master-via-blade-view-name" aria-label="Permalink to &quot;Optional: single master via \`blade_view_name\`&quot;">​</a></h3><p>When you do set an explicit view (instead of a slug pack):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cms:layout-builder:publish-blades</span></span></code></pre></div><table><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>File</td><td><code>resources/views/vendor/modularous/cms/layout-builder/master.blade.php</code></td></tr><tr><td>Suggested <code>blade_view_name</code></td><td><code>vendor.modularous.cms.layout-builder.master</code></td></tr></tbody></table><p>Slug packs take precedence over <code>blade_view_name</code> when any slug override file exists.</p><h2 id="stylesheets-on-a-builder" tabindex="-1">Stylesheets on a builder <a class="header-anchor" href="#stylesheets-on-a-builder" aria-label="Permalink to &quot;Stylesheets on a builder&quot;">​</a></h2><ul><li><code>style_sheet_id</code> — primary published <a href="./stylesheets">StyleSheet</a></li><li><code>style_sheet_slugs</code> — extra published slugs after the FK (duplicates skipped)</li></ul><p><code>StylesheetManager::linkHrefsForLayoutBuilder()</code> emits framework + compiled bundle <code>&lt;link&gt;</code> hrefs in that order.</p><h2 id="nested-body-compose" tabindex="-1">Nested body compose <a class="header-anchor" href="#nested-body-compose" aria-label="Permalink to &quot;Nested body compose&quot;">​</a></h2><p>Optional: <code>definition.cms_page_layout_body_compose = wrap</code> — PageLayout body is compiled first and passed into the LayoutBuilder body as <code>$cmsPageLayoutBodyHtml</code>. Default is append.</p><h2 id="admin-preview-middleware" tabindex="-1">Admin preview &amp; middleware <a class="header-anchor" href="#admin-preview-middleware" aria-label="Permalink to &quot;Admin preview &amp; middleware&quot;">​</a></h2><ul><li>Preview when <code>cms_layout_builder.preview_enabled</code> (default <strong>true</strong>)</li><li>Front middleware <code>modules.cms.layout_builder</code> is <strong>off</strong> by default; query key default <code>cms_layout</code></li><li><code>cms_layout_builder.default_layout_slug</code> — optional default theme slug</li></ul><h2 id="config-modularous-cms-layout-builder" tabindex="-1">Config (<code>modularous.cms_layout_builder</code>) <a class="header-anchor" href="#config-modularous-cms-layout-builder" aria-label="Permalink to &quot;Config (\`modularous.cms_layout_builder\`)&quot;">​</a></h2><table><thead><tr><th>Key</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>default_blade_source</code></td><td><code>db</code></td><td>Used when row omits <code>blade_source</code></td></tr><tr><td><code>max_blade_segments_bytes</code></td><td><code>512000</code></td><td>Cap for DB segments (UTF-8)</td></tr><tr><td><code>preview_enabled</code></td><td><code>true</code></td><td>Admin HTML preview</td></tr><tr><td><code>middleware_enabled</code></td><td><code>false</code></td><td>Opt-in query-param layout middleware</td></tr><tr><td><code>middleware_query_slug_key</code></td><td><code>cms_layout</code></td><td>Query key</td></tr><tr><td><code>default_layout_slug</code></td><td><code>&#39;&#39;</code></td><td>Fallback slug; also used by PageLayout default shell</td></tr></tbody></table><p>See also <a href="./configuration">Configuration</a>.</p><p><strong>Next:</strong> <a href="./page-layouts">Page layouts</a> — module/route <code>page_layout</code> blades with <code>NULL</code> <code>blade_view_name</code>.</p>`,41),l=[o];function i(r,c,n,u,p,h){return d(),a("div",null,l)}const g=e(s,[["render",i]]);export{m as __pageData,g as default};
